Sure! Here’s a clean, reusable TypeScript debounce function:

```typescript
function debounce<T extends (...args: any[]) => any>(
  fn: T,
  wait: number,
  options?: {
    leading?: boolean;
    trailing?: boolean;
  }
): (...args: Parameters<T>) => void {
  let lastCall = 0;
  let timeoutId: NodeJS.Timeout | null = null;

  const debounced = (...args: Parameters<T>) => {
    const now = Date.now();
    const elapsed = now - lastCall;

    // Handle leading/trailing logic if needed
    if (options?.leading && !timeoutId) {
      // Call immediately if leading is true
      fn(...args);
      lastCall = now;
    }

    // Cancel previous timeout if leading is false
    if (options?.trailing && timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }

    // Schedule the actual function call
    if (options?.trailing || !options?.leading) {
      timeoutId = setTimeout(() => {
        fn(...args);
        lastCall = Date.now();
      }, wait - elapsed);
    } else {
      // Leading case: call immediately and reset timer
      fn(...args);
      lastCall = now;
    }
  };

  // Initial call handling
  if (options?.leading) {
    debounced.call(null, ...args);
  }

  return debounced;
}
```

You can use it like:

```typescript
const debouncedFn = debounce(
  (value: number) => console.log(`Value: ${value}`),
  300 // wait 300 ms
);

